package org.usbworkbench;
import java.io.*;import java.util.*;
public final class ConsolePartsTest{
 static int checks;static void yes(boolean b){if(!b)throw new AssertionError();checks++;}interface Task{void run()throws Exception;}static void reject(Task task,String code)throws Exception{try{task.run();throw new AssertionError("Expected "+code);}catch(IOException e){if(!e.getMessage().startsWith(code))throw e;checks++;}}
 static class Source implements OpticalImage.Source{byte[] b;Source(byte[] b){this.b=b;}public long size(){return b.length;}public void read(long at,byte[] out,int off,int n){System.arraycopy(b,(int)at,out,off,n);}public void close(){}}
 static class Sink implements ConsoleParts.Sink{Map<String,ByteArrayOutputStream> files=new LinkedHashMap<>();boolean corrupt;public OutputStream create(String name)throws IOException{if(files.containsKey(name))throw new IOException("FILE_EXISTS");ByteArrayOutputStream out=new ByteArrayOutputStream();files.put(name,out);return out;}public InputStream reopen(String name){byte[] b=files.get(name).toByteArray();if(corrupt)b[0]^=1;return new ByteArrayInputStream(b);}public void sync(String name){}Map<String,ConsoleParts.Part> parts(ConsoleParts.Manifest m){Map<String,ConsoleParts.Part> out=new HashMap<>();for(int i=m.pieces.size()-1;i>=0;i--){String name=m.partName(i);out.put(name,new ConsoleParts.Part(){public long size(){return files.get(name).size();}public InputStream input(){return reopen(name);}});}return out;}}
 public static void main(String[] args)throws Exception{byte[] original=new byte[40*2048];new Random(221).nextBytes(original);
 for(String kind:new String[]{"iso","666"}){Sink sink=new Sink();String name=kind.equals("iso")?"قرص.iso":"ملف.bin";ConsoleParts.Manifest m=ConsoleParts.split(new Source(original),name,kind,6144,sink,(a,b)->{});yes(m.pieces.size()==14);yes(sink.files.containsKey(kind.equals("iso")?name+".10":name+".66610"));if(kind.equals("iso")){java.nio.file.Path root=java.nio.file.Paths.get("artifacts/console-fixtures");java.nio.file.Files.createDirectories(root);java.nio.file.Files.write(root.resolve("original.bin"),original);for(Map.Entry<String,ByteArrayOutputStream> e:sink.files.entrySet())java.nio.file.Files.write(root.resolve(e.getKey()),e.getValue().toByteArray());}byte[] encoded=m.encode();ConsoleParts.Manifest saved=ConsoleParts.read(new ByteArrayInputStream(encoded));yes(saved.hash().equals(m.hash()));yes(Arrays.equals(Arrays.copyOf(original,6144),sink.files.get(m.partName(0)).toByteArray()));Map<String,ConsoleParts.Part> parts=sink.parts(m);ByteArrayOutputStream out=new ByteArrayOutputStream();ConsoleParts.join(saved,parts,out,(a,b)->{});yes(Arrays.equals(original,out.toByteArray()));ConsoleParts.verifyJoined(m,new ByteArrayInputStream(out.toByteArray()),(a,b)->{});yes(true);parts.remove(m.partName(3));reject(()->ConsoleParts.join(m,parts,new ByteArrayOutputStream(),(a,b)->{}),"CONSOLE_PARTS");parts.put(m.partName(3),sink.parts(m).get(m.partName(3)));sink.corrupt=true;reject(()->ConsoleParts.join(m,parts,new ByteArrayOutputStream(),(a,b)->{}),"CONSOLE_PART_CORRUPT");sink.corrupt=false;encoded[12]^=1;reject(()->ConsoleParts.read(new ByteArrayInputStream(encoded)),"CONSOLE_MANIFEST");byte[] bad=original.clone();bad[0]^=1;reject(()->ConsoleParts.verifyJoined(m,new ByteArrayInputStream(bad),(a,b)->{}),"VERIFY_FAILED");}
 reject(()->ConsoleParts.split(new Source(original),"../disc.iso","iso",2048,new Sink(),(a,b)->{}),"CONSOLE_NAME");reject(()->ConsoleParts.split(new Source(original),"CON.iso","iso",2048,new Sink(),(a,b)->{}),"CONSOLE_NAME");reject(()->ConsoleParts.split(new Source(new byte[2049]),"disc.iso","iso",2048,new Sink(),(a,b)->{}),"CONSOLE_OPTIONS");Sink corrupt=new Sink();corrupt.corrupt=true;reject(()->ConsoleParts.split(new Source(original),"disc.iso","iso",6144,corrupt,(a,b)->{}),"VERIFY_FAILED");reject(()->ConsoleParts.split(new Source(original),"disc.iso","iso",6144,new Sink(),(a,b)->{throw new IOException("CANCELLED");}),"CANCELLED");
 System.out.println("PASS: "+checks+" standard ISO.#/.666NN raw parts, numeric ordering, Arabic names, checksummed manifests, missing/corrupt parts, readback, cancellation and safe names");
 }
}
